"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[48035],{3973:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"JunkService","desc":"Authoritative server script that drives the junk economy for Endless Journey.\\nRuns a timed spawn loop that performs two-stage weighted selection \u2014 first a\\ntier roll (multiplied by live `GlobalModifiers.TierMultipliers`), then a type\\nroll within that tier \u2014 with an energy-pity counter that guarantees an Energy\\nitem after `ENERGY_PITY_THRESHOLD` consecutive non-energy spawns.\\n\\nAll active junk is tracked by a global distance odometer; a piece despawns\\nautomatically once it has travelled past `DESPAWN_DISTANCE`, keeping memory\\nand network traffic bounded without a per-frame scan of every client.\\n\\nClaim/finalize follows a two-step reservation protocol: `ReqJunkClaim` checks\\nserver-side proximity (reconstructed from the shared odometer) and sets a\\ntimed reservation, while `ReqJunkFinalize` validates the reservation and\\nhands the junk Tool to the player\'s Backpack via `JunkToolManager`.","realm":["Server"],"source":{"line":20,"path":"src/ServerScriptService/JunkService.server.luau"}}')}}]);